template <>
inline Ark_RuntimeType runtimeType(const Ark_StyledStringValue& value)
{
    switch (value.selector) {
        case 0: return runtimeType(value.value0);
        case 1: return runtimeType(value.value1);
        case 2: return runtimeType(value.value2);
        case 3: return runtimeType(value.value3);
        case 4: return runtimeType(value.value4);
        case 5: return runtimeType(value.value5);
        case 6: return runtimeType(value.value6);
        case 7: return runtimeType(value.value7);
        case 8: return runtimeType(value.value8);
        case 9: return runtimeType(value.value9);
        case 10: return runtimeType(value.value10);
        case 11: return runtimeType(value.value11);
        case 12: return runtimeType(value.value12);
        default: INTEROP_FATAL("Bad selector in Ark_StyledStringValue: %d", value.selector);
    }
}
